        [MenuItem("Thermal/History Check")]
        static void Run()
        {
            int failed = 0, checks = 0;
            void Report(bool ok, string line)
            {
                checks++;
                if (ok) Debug.Log("[History] " + line);
                else { failed++; Debug.LogError("[History] " + line); }
            }

            // erfcx: numerics the weights stand on
            double worstErfcx = 0;
            foreach (var (x, value) in k_Erfcx)
            {
                double got = ThermalSpecialFunctions.Erfcx(x), off = (got - value) / value;
                bool ok = Math.Abs(off) <= k_ErfcxTolerance;
                worstErfcx = Math.Max(worstErfcx, double.IsNaN(off) ? double.PositiveInfinity : Math.Abs(off));
                Report(ok, string.Format(CultureInfo.InvariantCulture, "erfcx({0,-8:G}) {1,22:R} ({2:+0.0e+0;-0.0e+0} relative)   {3}",
                                         x, got, off, ok ? "ok" : "FAIL"));
            }

            // The weights (C#)
            double worstWeight = 0;
            foreach (var c in k_Weights)
            {
                var got = new double[c.lags.Length];
                ThermalMath.HistoryWeights(c.effusivity, c.conductance, c.lags, got);
                double off = 0, sum = 0;
                for (int i = 0; i < got.Length; i++)
                {
                    double d = Math.Abs(got[i] - c.weights[i]);
                    off = double.IsNaN(d) ? double.PositiveInfinity : Math.Max(off, d);
                    sum += got[i];
                }
                bool ok = off <= c.tolerance && Math.Abs(sum - 1.0) <= k_SumTolerance;
                if (c.tolerance <= 1e-9)
                    worstWeight = Math.Max(worstWeight, off);
                Report(ok, string.Format(CultureInfo.InvariantCulture,
                    "weights  {0,-14} {1,-8} e {2,8:G} H {3,5:F1}: now {4:F6}, oldest {5:F6}, worst {6:0.0e+0} " +
                    "(limit {7:0e+0}), sum - 1 {8:+0.0e+0;-0.0e+0}   {9}",
                    c.name, c.spacing, c.effusivity, c.conductance, got[0], got[got.Length - 1], off, c.tolerance,
                    sum - 1.0, ok ? "ok" : "FAIL"));
            }

            // The balance (HLSL)
            string balance = RunBalance(Report);

            string summary = string.Format(CultureInfo.InvariantCulture, "worst erfcx {0:0.0e+0} relative; worst weight " +
                                           "{1:0.0e+0}; {2}", worstErfcx, worstWeight, balance);
            if (failed == 0)
                Debug.Log($"[History] all {checks} checks passed: {summary}");
            else
                Debug.LogError($"[History] {failed} of {checks} checks FAILED: {summary}");
        }

        static string RunBalance(Action<bool, string> report)
        {
            var shader = AssetDatabase.LoadAssetAtPath<ComputeShader>(k_Shader);
            if (shader == null)
            {
                Debug.LogError($"[History] {k_Shader} is missing");
                return "balance not run";
            }

            // A contract the physics no longer meets shows as compile errors, with ThermalPhysics.hlsl's lines.
            int errors = 0;
            foreach (ShaderMessage m in ShaderUtil.GetComputeShaderMessages(shader))
            {
                if (m.severity != UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error)
                    continue;
                errors++;
                Debug.LogError($"[History] does not compile: {m.message} ({m.file}:{m.line})");
            }
            if (errors > 0)
            {
                Debug.LogError("[History] the check is written against THERMAL_HISTORY_SAMPLES (8), struct ThermalHistory " +
                               "{ ThermalEnvironment past[]; float weight[]; } and EnergyBalance MakeHistoryBalance(float3 N, " +
                               "ThermalSurface s, ThermalHistory h): rename them here or there");
                report(false, "the balance's kernels do not compile");
                return "balance does not compile";
            }

            // The plumbing first, so a buffer fault never passes for a physics fault.
            var cases = new float[k_Balance.Length * k_CaseFloats];
            for (int i = 0; i < k_Balance.Length; i++)
            {
                if (k_Balance[i].values.Length != k_CaseFloats)
                    throw new InvalidOperationException($"case {k_Balance[i].name} has {k_Balance[i].values.Length} floats");
                Array.Copy(k_Balance[i].values, 0, cases, i * k_CaseFloats, k_CaseFloats);
            }
            using var input = new ComputeBuffer(cases.Length, sizeof(float));
            input.SetData(cases);

            int echoKernel = shader.FindKernel("Echo");
            using (var echo = new ComputeBuffer(cases.Length, sizeof(float)))
            {
                echo.SetData(Filled(cases.Length, float.NaN));
                shader.SetBuffer(echoKernel, "_Cases", input);
                shader.SetBuffer(echoKernel, "_Echo", echo);
                shader.SetInt("_Count", k_Balance.Length);
                shader.Dispatch(echoKernel, (cases.Length + 63) / 64, 1, 1);
                var got = new float[cases.Length];
                echo.GetData(got);
                int differ = 0;
                for (int i = 0; i < cases.Length; i++)
                    if (BitConverter.SingleToInt32Bits(got[i]) != BitConverter.SingleToInt32Bits(cases[i]))
                        differ++;
                if (differ > 0)
                {
                    report(false, $"the check's own buffer is wrong: {differ} of {cases.Length} floats came back changed");
                    return "balance not run";
                }
                Debug.Log($"[History] buffer: {cases.Length} floats of {k_Balance.Length} cases read back exactly");
            }

            int kernel = shader.FindKernel("Balance");
            var t = new float[k_Balance.Length];
            using (var output = new ComputeBuffer(k_Balance.Length, sizeof(float)))
            {
                output.SetData(Filled(k_Balance.Length, float.NaN));      // a kernel that never wrote shows as NaN
                shader.SetBuffer(kernel, "_Cases", input);
                shader.SetBuffer(kernel, "_BalanceOut", output);
                shader.SetInt("_Count", k_Balance.Length);
                shader.Dispatch(kernel, (k_Balance.Length + 63) / 64, 1, 1);
                output.GetData(t);
            }

            double worstT = 0;
            for (int i = 0; i < k_Balance.Length; i++)
            {
                var c = k_Balance[i];
                double off = t[i] - c.t;
                bool ok = Math.Abs(off) <= k_TemperatureTolerance;
                worstT = Math.Max(worstT, double.IsNaN(off) ? double.PositiveInfinity : Math.Abs(off));
                report(ok, string.Format(CultureInfo.InvariantCulture, "T  {0,-30} {1,10:F4} K ({2:+0.0e+0;-0.0e+0})   {3}",
                                         c.name, t[i], off, ok ? "ok" : "FAIL"));
            }
            return string.Format(CultureInfo.InvariantCulture, "worst T {0:0.0e+0} K", worstT);
        }

        static float[] Filled(int length, float value)
        {
            var a = new float[length];
            for (int i = 0; i < length; i++)
                a[i] = value;
            return a;
        }
    }
}
